const crypto = require("crypto");

const PRIVATE_KEY = String($('Config Local').first().json.FLOW_PRIVATE_KEY)
  .replace(/\\n/g, "\n")
  .trim();
if (!PRIVATE_KEY || PRIVATE_KEY.includes("COLE_AQUI")) {
  throw new Error('Cole a chave privada RSA (PEM) no no "Config Local"');
}

const wh = $('Flow Endpoint Webhook').first().json;
const body = wh.body || wh;
const { encrypted_aes_key, encrypted_flow_data, initial_vector } = body;
if (!encrypted_aes_key || !encrypted_flow_data || !initial_vector) {
  throw new Error("Request nao e um WhatsApp Flow (campos encrypted_* ausentes)");
}

const aesKeyBuffer = crypto.privateDecrypt(
  { key: crypto.createPrivateKey(PRIVATE_KEY), padding: crypto.constants.RSA_PKCS1_OAEP_PADDING, oaepHash: "sha256" },
  Buffer.from(encrypted_aes_key, "base64"),
);

const flowDataBuffer = Buffer.from(encrypted_flow_data, "base64");
const ivBuffer = Buffer.from(initial_vector, "base64");
const TAG_LENGTH = 16;
const encryptedBody = flowDataBuffer.subarray(0, -TAG_LENGTH);
const authTag = flowDataBuffer.subarray(-TAG_LENGTH);

const decipher = crypto.createDecipheriv("aes-128-gcm", aesKeyBuffer, ivBuffer);
decipher.setAuthTag(authTag);
const decryptedBody = JSON.parse(
  Buffer.concat([decipher.update(encryptedBody), decipher.final()]).toString("utf-8"),
);

const route = decryptedBody.action === 'data_exchange' ? (decryptedBody.screen || '') : decryptedBody.action;

return [{ json: { decryptedBody, aesKeyBuffer, ivBuffer, action: decryptedBody.action, screen: decryptedBody.screen || null, route } }];

const items = $input.all().map((i) => i.json);
const products = (items.length === 1 && Array.isArray(items[0])) ? items[0] : items;
const brl = (v) => 'R$ ' + Number(v || 0).toFixed(2).replace('.', ',');
const MAX_CATS = 12, MAX_PER_CAT = 20;
const groups = {}; const order = [];
products.forEach((p) => { const cat = (p.categ_id && p.categ_id.name) || 'Outros'; if (!groups[cat]) { groups[cat] = []; order.push(cat); } groups[cat].push(p); });
const warnings = [];
if (order.length > MAX_CATS) warnings.push('Categorias: ' + order.length + ' no total, cortou ' + (order.length - MAX_CATS));
const data = {};
order.slice(0, MAX_CATS).forEach((cat, i) => {
  const n = i + 1; const list = groups[cat];
  if (list.length > MAX_PER_CAT) warnings.push('Categoria "' + cat + '": ' + list.length + ' itens, cortou ' + (list.length - MAX_PER_CAT));
  data['cat_' + n + '_name'] = String(cat).slice(0, 30);
  data['cat_' + n + '_visible'] = true;
  data['cat_' + n + '_items'] = list.slice(0, MAX_PER_CAT).map((p) => ({ id: String(p.id), title: String(p.name || '').slice(0, 30), description: brl(p.list_price) }));
});
for (let n = 1; n <= MAX_CATS; n++) { if (!data['cat_' + n + '_visible']) { data['cat_' + n + '_name'] = ''; data['cat_' + n + '_visible'] = false; data['cat_' + n + '_items'] = [{ id: '_', title: '-' }]; } }
data.has_notice = false;
data.notice = '';
if (warnings.length) console.log('[FLOW PRODUCTS overflow]', warnings.join(' | '));
return [{ json: { response_to_send: { screen: 'PRODUCTS', data }, _warnings: warnings } }];

const items = $input.all().map((i) => i.json);
const products = (items.length === 1 && Array.isArray(items[0])) ? items[0] : items;
const byId = {};
products.forEach((p) => { byId[String(p.id)] = p; });
const d = ($('Decryption').first().json.decryptedBody.data) || {};
const MAX_CATS = 12, MAX_SLOTS = 20;
let selected = [];
for (let c = 1; c <= MAX_CATS; c++) {
  let arr = d['selected_' + c];
  if (arr == null) continue;
  if (!Array.isArray(arr)) arr = [arr];
  arr.forEach((v) => { String(v).split(',').forEach((x) => selected.push(x)); });
}
selected = selected.map((x) => String(x).trim()).filter((x) => x && x !== '_');
selected = selected.filter((x, i) => selected.indexOf(x) === i);
if (selected.length === 0) {
  const brl = (v) => 'R$ ' + Number(v || 0).toFixed(2).replace('.', ',');
  const MAX_PER_CAT = 20;
  const groups = {}; const order = [];
  products.forEach((p) => { const cat = (p.categ_id && p.categ_id.name) || 'Outros'; if (!groups[cat]) { groups[cat] = []; order.push(cat); } groups[cat].push(p); });
  const data = {};
  order.slice(0, MAX_CATS).forEach((cat, i) => {
    const n = i + 1; const list = groups[cat];
    data['cat_' + n + '_name'] = String(cat).slice(0, 30);
    data['cat_' + n + '_visible'] = true;
    data['cat_' + n + '_items'] = list.slice(0, MAX_PER_CAT).map((p) => ({ id: String(p.id), title: String(p.name || '').slice(0, 30), description: brl(p.list_price) }));
  });
  for (let n = 1; n <= MAX_CATS; n++) { if (!data['cat_' + n + '_visible']) { data['cat_' + n + '_name'] = ''; data['cat_' + n + '_visible'] = false; data['cat_' + n + '_items'] = [{ id: '_', title: '-' }]; } }
  data.has_notice = true;
  data.notice = '\u26a0\ufe0f Selecione ao menos um item para continuar!';
  return [{ json: { response_to_send: { screen: 'PRODUCTS', data } } }];
}
const warnings = [];
if (selected.length > MAX_SLOTS) warnings.push('Itens selecionados: ' + selected.length + ', cortou ' + (selected.length - MAX_SLOTS));
const out = {};
selected.slice(0, MAX_SLOTS).forEach((pid, i) => {
  const n = i + 1; const p = byId[String(pid)] || {};
  out['slot_' + n + '_id'] = String(pid);
  out['slot_' + n + '_title'] = String(p.name || ('Produto ' + pid)).slice(0, 20);
  out['slot_' + n + '_visible'] = true;
});
for (let n = 1; n <= MAX_SLOTS; n++) { if (!out['slot_' + n + '_visible']) { out['slot_' + n + '_id'] = ''; out['slot_' + n + '_title'] = ''; out['slot_' + n + '_visible'] = false; } }
const catmap = {};
selected.slice(0, MAX_SLOTS).forEach((pid) => { const pp = byId[String(pid)] || {}; catmap[String(pid)] = (pp.categ_id && pp.categ_id.name) || 'Outros'; });
out.catmap = JSON.stringify(catmap);
out.has_notice = warnings.length > 0;
out.notice = warnings.length ? ('Aviso (corte): ' + warnings.join(' | ')) : '';
if (warnings.length) console.log('[FLOW QUANTITIES overflow]', warnings.join(' | '));
return [{ json: { response_to_send: { screen: 'QUANTITIES', data: out }, _warnings: warnings } }];

const data = ($('Decryption').first().json.decryptedBody.data) || {};
const MAX_SLOTS = 20;
const cart = [];
let catmap = {};
try { catmap = JSON.parse(data.catmap || '{}'); } catch (e) { catmap = {}; }
for (let n = 1; n <= MAX_SLOTS; n++) {
  const id = data['id' + n]; const q = parseInt(data['q' + n], 10);
  if (id && q > 0) cart.push({ product_id: Number(id), quantity: q, note: data['obs' + n] || '', category: catmap[String(id)] || 'Outros' });
}
const cutlery = data.cutlery || 'nao';
let customer = null;
try {
  const searchResult = $('Busca Cliente').first().json;
  if (searchResult && searchResult.id) customer = searchResult;
  else if (Array.isArray(searchResult)) customer = searchResult[0] || null;
} catch(e) { console.log('[Monta DELIVERY] Sem resultado busca cliente:', e.message); }
const flowToken = $('Decryption').first().json.decryptedBody.flow_token || '';
const tokenBody = flowToken.replace('aurora-rest-', '');
const lastDash = tokenBody.lastIndexOf('-');
const customerPhone = lastDash > 0 ? tokenBody.substring(0, lastDash) : tokenBody;
const deliveryData = {
  cart: JSON.stringify(cart),
  cutlery,
  customer_phone: customerPhone,
  customer_name: (customer && customer.name) || 'Cliente WhatsApp',
  partner_id: (customer && customer.id) ? String(customer.id) : '',
};
const addresses = (customer && customer.delivery_addresses) || [];
if (addresses.length > 0) {
  const firstAddr = addresses[0];
  const firstId = String(firstAddr.id) + '::' + (firstAddr.street || ('Endereco ' + firstAddr.id));
  deliveryData.has_addresses = true;
  deliveryData.show_dropdown = true;
  deliveryData.show_form = false;
  deliveryData.default_address = firstId;
  deliveryData.default_use_existing = 'sim';
  deliveryData.address_items = addresses.map(a => ({
    id: String(a.id) + '::' + (a.street || ('Endereco ' + a.id)),
    title: a.street || ('Endereco ' + a.id)
  }));
} else {
  deliveryData.has_addresses = false;
  deliveryData.show_dropdown = false;
  deliveryData.show_form = true;
  deliveryData.default_address = '';
  deliveryData.default_use_existing = '';
  deliveryData.address_items = [{ id: '_', title: '-' }];
}
return [{ json: { response_to_send: { screen: 'DELIVERY', data: deliveryData } } }];

const data = ($('Decryption').first().json.decryptedBody.data) || {};
if (data.is_toggle === 'true' || data.is_toggle === true) {
  const isSim = data.use_existing === 'sim';
  let addrItems;
  try { addrItems = typeof data.address_items === 'string' ? JSON.parse(data.address_items) : data.address_items; } catch(e) { addrItems = [{ id: '_', title: '-' }]; }
  if (!Array.isArray(addrItems) || addrItems.length === 0) addrItems = [{ id: '_', title: '-' }];
  return [{ json: { is_rerender: true, response_to_send: { screen: 'DELIVERY', data: {
    cart: data.cart,
    cutlery: data.cutlery,
    has_addresses: true,
    show_dropdown: isSim,
    show_form: !isSim,
    address_items: addrItems,
    default_address: data.default_address || '',
    default_use_existing: data.use_existing,
    partner_id: data.partner_id || '',
    customer_phone: data.customer_phone || '',
    customer_name: data.customer_name || '',
  } } } }];
}
if (data.use_existing === 'nao' && !data.street) {
  return [{ json: { is_rerender: true, response_to_send: { screen: 'DELIVERY', data: {
    cart: data.cart,
    cutlery: data.cutlery,
    has_addresses: false,
    show_dropdown: false,
    show_form: true,
    address_items: [{ id: '_', title: '-' }],
    default_address: '',
    default_use_existing: '',
    partner_id: data.partner_id || '',
    customer_phone: data.customer_phone || '',
    customer_name: data.customer_name || '',
  } } } }];
}
const cart = JSON.parse(data.cart || '[]');
const cutlery = data.cutlery || 'nao';
const POS = Number($('Config Local').first().json.ODOO_POS_CONFIG_ID);
const customerPhone = data.customer_phone || '';
const customerName = data.customer_name || 'Cliente WhatsApp';
const partnerId = data.partner_id || '';
const quoteBody = { pos_config_id: POS, lines: cart.map((c) => ({ product_id: c.product_id, quantity: c.quantity })) };
const orderPayload = {
  pos_config_id: POS,
  order_type: 'delivery',
  lines: cart.map((c) => ({ product_id: c.product_id, quantity: c.quantity, note: c.note || undefined })),
  cutlery: cutlery === 'sim',
  source: 'whatsapp_flow',
};
let addressText = '';
if (data.use_existing === 'sim' && data.selected_address) {
  const parts = data.selected_address.split('::');
  const addressId = Number(parts[0]);
  addressText = parts[1] || '';
  orderPayload.partner_id = Number(partnerId);
  orderPayload.delivery_address = { id: addressId };
} else {
  orderPayload.customer = { name: customerName, phone: customerPhone || 'sem-telefone' };
  if (partnerId) orderPayload.partner_id = Number(partnerId);
  orderPayload.delivery_address = {
    new: { street: (data.street || '') + (data.number ? ', ' + data.number : ''), street2: data.complement || null, city: data.neighborhood || null },
    add_new_address: true,
  };
}
return [{ json: { is_rerender: false, quoteBody, orderPayload, cutlery, addressText } }];

const quote = $input.first().json;
const prep = $('Prep Quote').first().json;
const data = ($('Decryption').first().json.decryptedBody.data) || {};
const brl = (v) => 'R$ ' + Number(v || 0).toFixed(2).replace('.', ',');
const NL = String.fromCharCode(10);
const cart = JSON.parse(data.cart || '[]');
const groups = {}; const catOrder = [];
(quote.lines || []).forEach((l, i) => {
  const cat = (cart[i] && cart[i].category) || 'Outros';
  const name = (l.product_id && l.product_id.name) || 'item';
  const note = (cart[i] && cart[i].note) ? (' (' + cart[i].note + ')') : '';
  if (!groups[cat]) { groups[cat] = []; catOrder.push(cat); }
  groups[cat].push(name + ' ' + l.quantity + 'x' + note);
});
const items_text = catOrder.map((cat) => cat + NL + groups[cat].join(NL)).join(NL + NL) || '(itens)';
const FRETE = 0;
const subtotal = Number(quote.amount_untaxed || 0);
const subtotal_text = 'Subtotal: ' + brl(subtotal);
const delivery_fee_text = 'Frete: ' + brl(FRETE);
const taxParts = [];
(quote.lines || []).forEach((l) => { (l.taxes || []).forEach((t) => { const taxName = (t.tax_id && t.tax_id.name) || 'Taxa'; taxParts.push(taxName + ': ' + brl(t.amount)); }); });
const totalVal = Number(quote.amount_total || 0) + FRETE;
const total_text = 'Total: ' + brl(totalVal);
const cutleryText = prep.cutlery === 'sim' ? 'Sim' : 'Não';
const addrText = prep.addressText || '';
const delivery_text = addrText ? ('Entrega: ' + addrText + NL + 'Talheres: ' + cutleryText) : ('Entrega: ' + [[data.street, data.number].filter(Boolean).join(', '), data.neighborhood].filter(Boolean).join(' - ') + NL + 'Talheres: ' + cutleryText);
const tax_total = taxParts.length ? 'Taxas: ' + taxParts.join(' | ') : '';
return [{ json: { response_to_send: { screen: 'PAYMENT', data: { items_text: items_text || '(itens)', subtotal_text, delivery_fee_text, total_text, delivery_text, tax_total, order_payload: JSON.stringify(prep.orderPayload) } } } }];

const data = ($('Decryption').first().json.decryptedBody.data) || {};
let op = {};
try { op = JSON.parse(data.order_payload || '{}'); } catch (e) { op = {}; }
const pm = data.payment_method || 'online';
let payment_text;
if (pm === 'online') {
  op.payment = { type: 'online', method: 'mercado_pago' };
  payment_text = 'Pagamento: Online (Mercado Pago)';
} else {
  const pt = data.payment_type || 'pix';
  const PT = { pix: 'Pix', debito: 'Cartão de débito', credito: 'Cartão de crédito' };
  op.payment = { type: 'on_delivery', method: pt };
  payment_text = 'Pagamento na entrega: ' + (PT[pt] || pt);
}
const flowToken = ($('Decryption').first().json.decryptedBody.flow_token) || '';
return [{ json: { response_to_send: { screen: 'SUMMARY', data: {
  items_text: data.items_text || '(itens)',
  subtotal_text: data.subtotal_text || '',
  delivery_fee_text: data.delivery_fee_text || '',
  tax_total: data.tax_total || '',
  total_text: data.total_text || '',
  delivery_text: data.delivery_text || '',
  payment_text,
  flow_token: flowToken,
  order_payload: JSON.stringify(op)
} } } }];

const d = $('Decryption').first().json;
let response_to_send;
if (d.action === 'BACK') { response_to_send = { screen: d.screen || 'PRODUCTS', data: {} }; }
else { response_to_send = { data: { acknowledged: true } }; }
return [{ json: { response_to_send } }];

const crypto = require("crypto");

const responsePayload = $input.first().json.response_to_send;

const aesKeyBuffer = Buffer.from($('Decryption').first().json.aesKeyBuffer.data);
const ivBuffer = Buffer.from($('Decryption').first().json.ivBuffer.data);
const flippedIV = Buffer.from(ivBuffer.map((b) => ~b));

const cipher = crypto.createCipheriv("aes-128-gcm", aesKeyBuffer, flippedIV);
const encryptedResponse = Buffer.concat([
  cipher.update(JSON.stringify(responsePayload), "utf-8"),
  cipher.final(),
  cipher.getAuthTag(),
]);

return [{ json: { response: encryptedResponse.toString("base64") } }];
